{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"authorship_tag":"ABX9TyNcTWlTthbm5EiQFBGycuym"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","execution_count":null,"metadata":{"id":"jd0JYraJzD6O"},"outputs":[],"source":["import os\n","import cv2\n","import numpy as np\n","import matplotlib.pyplot as plt\n","import seaborn as sns\n","import joblib\n","from tqdm import tqdm\n","from sklearn.model_selection import train_test_split\n","from sklearn.ensemble import RandomForestClassifier\n","from sklearn.neighbors import KNeighborsClassifier\n","from sklearn.feature_selection import RFE\n","from sklearn.metrics import classification_report, confusion_matrix\n","from skimage.feature import local_binary_pattern\n","from albumentations import Compose, Resize, HorizontalFlip, RandomBrightnessContrast, CLAHE, GaussNoise, HueSaturationValue\n","\n","import tensorflow as tf\n","from tensorflow.keras.applications import VGG16, EfficientNetB0\n","from tensorflow.keras.applications.vgg16 import preprocess_input as vgg_preprocess\n","from tensorflow.keras.preprocessing.image import img_to_array\n","from tensorflow.keras.models import Model\n","from tensorflow.keras.layers import Dense, GlobalAveragePooling2D\n","\n","def load_images_with_labels(fire_dirs, non_fire_dirs, image_size=(224, 224)):\n","    data, labels = [], []\n","    for label, dirs in enumerate([non_fire_dirs, fire_dirs]):\n","        for folder in dirs:\n","            if not os.path.exists(folder):\n","                continue\n","            for filename in tqdm(os.listdir(folder), desc=f\"Loading {os.path.basename(folder)}\"):\n","                try:\n","                    file_path = os.path.join(folder, filename)\n","                    img = cv2.imread(file_path)\n","                    if img is not None:\n","                        img = cv2.resize(img, image_size)\n","                        data.append(img)\n","                        labels.append(label)\n","                except:\n","                    continue\n","    return np.array(data), np.array(labels)\n","\n","augmentation_pipeline = Compose([\n","    Resize(224, 224),\n","    HorizontalFlip(p=0.5),\n","    RandomBrightnessContrast(p=0.5),\n","    CLAHE(p=0.3),\n","    GaussNoise(p=0.2),\n","    HueSaturationValue(p=0.3)\n","])\n","\n","def augment_data(images):\n","    return np.array([augmentation_pipeline(image=img)['image'] for img in images])\n","\n","vgg_feat_extractor = VGG16(weights='imagenet', include_top=False, input_shape=(224, 224, 3))\n","\n","def extract_hsv_histogram(image):\n","    hsv = cv2.cvtColor(image, cv2.COLOR_BGR2HSV)\n","    hist = cv2.calcHist([hsv], [0, 1, 2], None, [8, 8, 8], [0, 180, 0, 256, 0, 256])\n","    return cv2.normalize(hist, hist).flatten()\n","\n","def extract_lbp_texture(image):\n","    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)\n","    lbp = local_binary_pattern(gray, P=8, R=1, method='uniform')\n","    (hist, _) = np.histogram(lbp.ravel(), bins=np.arange(0, 11), range=(0, 10))\n","    return hist.astype(\"float\") / (hist.sum() + 1e-7)\n","\n","def extract_vgg_deep_features(image):\n","    img_rgb = cv2.cvtColor(image, cv2.COLOR_BGR2RGB)\n","    img_array = vgg_preprocess(np.expand_dims(img_to_array(img_rgb), axis=0))\n","    return vgg_feat_extractor.predict(img_array, verbose=0).flatten()\n","\n","def get_hybrid_features(images):\n","    all_feats = []\n","    for img in tqdm(images, desc=\"Extracting Hybrid Features\"):\n","        combined = np.concatenate([\n","            extract_hsv_histogram(img),\n","            extract_lbp_texture(img),\n","            extract_vgg_deep_features(img)\n","        ])\n","        all_feats.append(combined)\n","    return np.array(all_feats)\n","\n","def build_tl_model(base_model_class):\n","    base = base_model_class(weights='imagenet', include_top=False, input_shape=(224, 224, 3))\n","    base.trainable = False\n","    x = GlobalAveragePooling2D()(base.output)\n","    out = Dense(1, activation='sigmoid')(x)\n","    model = Model(inputs=base.input, outputs=out)\n","    model.compile(optimizer='adam', loss='binary_crossentropy', metrics=['accuracy'])\n","    return model\n","\n","from google.colab import drive\n","drive.mount('/content/drive')\n","\n","fire_folders = ['/content/drive/MyDrive/Dataset/Fire']\n","non_fire_folders = ['/content/drive/MyDrive/Dataset/Non_Fire']\n","\n","X_raw, y_raw = load_images_with_labels(fire_folders, non_fire_folders)\n","X_train_val, X_test, y_train_val, y_test = train_test_split(X_raw, y_raw, test_size=0.2, stratify=y_raw, random_state=42)\n","X_train, X_val, y_train, y_val = train_test_split(X_train_val, y_train_val, test_size=0.125, stratify=y_train_val, random_state=42)\n","\n","X_train_aug = augment_data(X_train)\n","\n","X_train_feats = get_hybrid_features(X_train_aug)\n","X_test_feats = get_hybrid_features(X_test)\n","\n","selector = RFE(RandomForestClassifier(n_estimators=100, random_state=42), n_features_to_select=300, step=100)\n","X_train_sel = selector.fit_transform(X_train_feats, y_train)\n","X_test_sel = selector.transform(X_test_feats)\n","\n","rf = RandomForestClassifier(n_estimators=100, random_state=42).fit(X_train_sel, y_train)\n","print(classification_report(y_test, rf.predict(X_test_sel)))\n","\n","knn = KNeighborsClassifier(n_neighbors=5).fit(X_train_sel, y_train)\n","print(classification_report(y_test, knn.predict(X_test_sel)))\n","\n","vgg_tl = build_tl_model(VGG16)\n","vgg_tl.fit(X_train_aug, y_train, validation_data=(X_val, y_val), epochs=10, batch_size=32)\n","\n","eff_tl = build_tl_model(EfficientNetB0)\n","eff_tl.fit(X_train_aug, y_train, validation_data=(X_val, y_val), epochs=10, batch_size=32)\n","\n","os.makedirs('/content/drive/MyDrive/Wildfire_Models', exist_ok=True)\n","joblib.dump(rf, '/content/drive/MyDrive/Wildfire_Models/rf_model.pkl')\n","joblib.dump(knn, '/content/drive/MyDrive/Wildfire_Models/knn_model.pkl')\n","joblib.dump(selector, '/content/drive/MyDrive/Wildfire_Models/feature_selector.pkl')\n","vgg_tl.save('/content/drive/MyDrive/Wildfire_Models/vgg16_model.h5')\n","eff_tl.save('/content/drive/MyDrive/Wildfire_Models/effnet_model.h5')"]}]}